INSERT IGNORE INTO screens (id,theatre_id,name,number,row_count,seats_per_row,status,created_at,updated_at) SELECT CONCAT('s',LPAD(n,2,'0')),CONCAT('t',LPAD(n,2,'0')), 'Main Screen',1,8,12,'ACTIVE',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10) x;
