


SELECT CONCAT('show',LPAD(n,2,'0')),CONCAT('m',LPAD(n,2,'0')),CONCAT('t',LPAD(n,2,'0')),CONCAT('s',LPAD(n,2,'0')),DATEADD('DAY', 2, CURRENT_DATE),'18:00:00','21:00:00','PAID',250,6,FALSE,'OPEN',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10) x;
